#include "cat.h"
#include "fs_utils.h"
#include <iostream>
void cat_cmd(std::vector<std::string>&p,EstadoGlobal&e){if(!e.sesionActiva){std::cout<<"[ERROR] No existe una sesion activa\n";return;}std::vector<std::string>paths;for(size_t i=1;i<p.size();++i){std::string n,v;if(!dividir_parametro(p[i],n,v)){std::cout<<"[ERROR] CAT usa -file1=/ruta, -file2=/ruta...\n";return;}std::string l=minusculas(n);if(l.rfind("file",0)==0||l=="path")paths.push_back(v);else{std::cout<<"[ERROR] Parametro no reconocido: -"<<n<<"\n";return;}}if(paths.empty()){std::cout<<"[ERROR] CAT requiere al menos un archivo\n";return;}UbicacionParticion part;if(!abrir_particion_por_sesion(e,part)){std::cout<<"[ERROR] Particion de sesion no disponible\n";return;}FILE*f=fopen(part.ruta.c_str(),"r+b");if(!f)return;sbloque sb;if(!leer_super(f,part,sb)){fclose(f);return;}for(auto&path:paths){int idx;if(!resolver_path(f,sb,path,idx)){std::cout<<"[ERROR] No existe el archivo: "<<path<<"\n";continue;}inodo ino;leer_inodo(f,sb,idx,ino);if(ino.i_type!='1'){std::cout<<"[ERROR] No es un archivo: "<<path<<"\n";continue;}if(!permiso_inodo(e,ino,4)){std::cout<<"[ERROR] Sin permiso de lectura: "<<path<<"\n";continue;}std::string c;leer_archivo(f,sb,idx,c);std::cout<<c;if(c.empty()||c.back()!='\n')std::cout<<"\n";}fclose(f);}
